using System.Text.Json;
using EvalToolkit.Core;

namespace EvalToolkit.EvalGen.Tests;

/// <summary>
/// Tests for the <c>EvalToolkit.Core</c> shared models. Lives in
/// EvalGen.Tests because EvalGen has the broadest dependency on Core
/// and we have no dedicated Core.Tests project yet (one will be added
/// only if Core's surface area outgrows piggy-backing here).
///
/// These gate the wire-format parity contract: enum string round-trips
/// and Assertion JSON round-trip both have to match the TS impl
/// byte-for-byte or eval files generated by one tool will silently
/// confuse the other.
/// </summary>
public class CoreModelsTests
{
    // ── Enum wire-string round-trips ─────────────────────────────────────

    [Theory]
    [InlineData(InputFormat.Csv, "csv")]
    [InlineData(InputFormat.Json, "json")]
    [InlineData(InputFormat.Jsonl, "jsonl")]
    [InlineData(InputFormat.Xlsx, "xlsx")]
    [InlineData(InputFormat.Docx, "docx")]
    [InlineData(InputFormat.Pdf, "pdf")]
    [InlineData(InputFormat.Pptx, "pptx")]
    [InlineData(InputFormat.Txt, "txt")]
    public void InputFormat_RoundTripsViaWireString(InputFormat format, string wire)
    {
        Assert.Equal(wire, format.ToWireString());
        Assert.Equal(format, InputFormats.FromWireString(wire));
    }

    [Fact]
    public void InputFormat_FromWireString_AcceptsTsvAsCsv()
    {
        // TS impl emits format: 'csv' for .tsv inputs (same parser, different delimiter).
        Assert.Equal(InputFormat.Csv, InputFormats.FromWireString("tsv"));
    }

    [Theory]
    [InlineData(LLMProvider.M365Copilot, "m365-copilot")]
    [InlineData(LLMProvider.M365CopilotApi, "m365-copilot-api")]
    [InlineData(LLMProvider.WorkIqA2a, "workiq-a2a")]
    [InlineData(LLMProvider.AzureOpenAi, "azure-openai")]
    [InlineData(LLMProvider.GitHubCopilot, "github-copilot")]
    [InlineData(LLMProvider.Command, "command")]
    public void LLMProvider_RoundTripsViaWireString(LLMProvider provider, string wire)
    {
        Assert.Equal(wire, provider.ToWireString());
        Assert.Equal(provider, LLMProviders.FromWireString(wire));
    }

    [Theory]
    [InlineData(QuestionCategory.SingleRecordLookup, "single_record_lookup")]
    [InlineData(QuestionCategory.AttributeRetrieval, "attribute_retrieval")]
    [InlineData(QuestionCategory.FilteredFind, "filtered_find")]
    [InlineData(QuestionCategory.Temporal, "temporal")]
    [InlineData(QuestionCategory.Comparison, "comparison")]
    [InlineData(QuestionCategory.EdgeCase, "edge_case")]
    public void QuestionCategory_RoundTripsViaWireString(QuestionCategory cat, string wire)
    {
        Assert.Equal(wire, cat.ToWireString());
        Assert.Equal(cat, QuestionCategories.FromWireString(wire));
    }

    [Fact]
    public void QuestionCategory_DefaultWeights_SumToOne()
    {
        double sum = 0;
        foreach (KeyValuePair<QuestionCategory, double> entry in QuestionCategories.DefaultWeights)
        {
            sum += entry.Value;
        }
        // Same numerics as TS DEFAULT_CATEGORY_WEIGHTS (0.3+0.2+0.2+0.1+0.1+0.1 = 1.0).
        Assert.Equal(1.0, sum, precision: 9);
    }

    // ── Assertion JSON round-trip ────────────────────────────────────────

    [Fact]
    public void Assertion_MustContain_RoundTrips_WithTsShape()
    {
        Assertion original = new MustContainAssertion { Value = "Acme", WholeWord = true };
        string json = JsonSerializer.Serialize(original);

        // Must emit the TS-compatible {type, value, wholeWord} shape — NOT $type.
        Assert.Contains("\"type\":\"must_contain\"", json);
        Assert.Contains("\"value\":\"Acme\"", json);
        Assert.Contains("\"wholeWord\":true", json);

        Assertion? decoded = JsonSerializer.Deserialize<Assertion>(json);
        Assert.Equal(original, decoded);
    }

    [Fact]
    public void Assertion_MustContain_OmitsWholeWord_WhenFalse()
    {
        // The TS impl makes wholeWord optional; matching that contract
        // keeps the byte-exact parity gate happy.
        Assertion original = new MustContainAssertion { Value = "Acme" };
        string json = JsonSerializer.Serialize(original);
        Assert.DoesNotContain("wholeWord", json, StringComparison.Ordinal);
    }

    [Fact]
    public void Assertion_MustContainAny_RoundTrips()
    {
        Assertion original = new MustContainAnyAssertion { Values = ["foo", "bar"] };
        string json = JsonSerializer.Serialize(original);

        Assert.Contains("\"type\":\"must_contain_any\"", json);
        Assert.Contains("\"values\":[\"foo\",\"bar\"]", json);

        Assertion? decoded = JsonSerializer.Deserialize<Assertion>(json);
        MustContainAnyAssertion typed = Assert.IsType<MustContainAnyAssertion>(decoded);
        Assert.Equal(new[] { "foo", "bar" }, typed.Values);
    }

    [Fact]
    public void Assertion_MustNotContain_RoundTrips()
    {
        Assertion original = new MustNotContainAssertion { Value = "internal" };
        string json = JsonSerializer.Serialize(original);

        Assert.Contains("\"type\":\"must_not_contain\"", json);

        Assertion? decoded = JsonSerializer.Deserialize<Assertion>(json);
        Assert.Equal(original, decoded);
    }

    [Fact]
    public void Assertion_Deserialize_ThrowsOnUnknownType()
    {
        string json = "{\"type\":\"must_levitate\",\"value\":\"x\"}";
        Assert.Throws<JsonException>(() => JsonSerializer.Deserialize<Assertion>(json));
    }

    [Fact]
    public void Assertion_Deserialize_ThrowsOnMissingTypeDiscriminator()
    {
        string json = "{\"value\":\"x\"}";
        Assert.Throws<JsonException>(() => JsonSerializer.Deserialize<Assertion>(json));
    }

    // ── StableIds parity with TS impl ────────────────────────────────────

    [Theory]
    [InlineData("What is the total revenue?", "invoices.csv:row=12", "6129e7c36138")]
    [InlineData("Q with | pipe in prompt", "src.md", "3094acedbb34")]
    [InlineData("", "", "cbe5cfdf7c21")]
    public void StableIds_ItemId_MatchesTsSha256Hex12(string prompt, string sourceLocation, string expected)
    {
        // Reference values produced by Node:
        //   crypto.createHash('sha256').update(`${prompt}|${sourceLocation}`).digest('hex').slice(0, 12)
        // Locked in here so we'd catch any regression that switches
        // algorithm, encoding, or slice length.
        Assert.Equal(expected, StableIds.ItemId(prompt, sourceLocation));
    }

    [Fact]
    public void StableIds_GroupHash_PrefersExistingItemIdOverPromptSourceJoin()
    {
        // TS impl: `item.id || `${prompt}|${source_location}`` — when
        // .id is non-empty, the JOIN piece is the id; otherwise the
        // prompt|source fallback. Then join all pieces with `|`.
        List<GeneratedEvalItem> group = new()
        {
            NewItem(id: "", prompt: "What is the total revenue?", source: "invoices.csv:row=12"),
            NewItem(id: "", prompt: "Other prompt", source: "src.csv"),
            NewItem(id: "abc123def456", prompt: "Ignored because Id is set", source: "ignored.csv"),
        };

        // Reference: sha256("What is the total revenue?|invoices.csv:row=12|Other prompt|src.csv|abc123def456").digest('hex').slice(0,12)
        Assert.Equal("324f3eef940e", StableIds.GroupHash(group));
    }

    private static GeneratedEvalItem NewItem(string id, string prompt, string source) => new()
    {
        Id = id,
        Prompt = prompt,
        ExpectedAnswer = string.Empty,
        SourceLocation = source,
        Assertions = Array.Empty<Assertion>(),
        Category = QuestionCategory.SingleRecordLookup,
        Difficulty = Difficulty.Easy,
        SupportingFacts = Array.Empty<string>(),
        GroundingConfidence = GroundingConfidence.High,
    };

    [Fact]
    public void StableIds_ItemId_IsDeterministic()
    {
        string a = StableIds.ItemId("hello", "world.csv");
        string b = StableIds.ItemId("hello", "world.csv");
        Assert.Equal(a, b);
        Assert.Equal(12, a.Length);
    }

    [Fact]
    public void StableIds_ItemId_ChangesWithEitherInput()
    {
        string a = StableIds.ItemId("hello", "world.csv");
        string b = StableIds.ItemId("hello!", "world.csv");
        string c = StableIds.ItemId("hello", "world2.csv");
        Assert.NotEqual(a, b);
        Assert.NotEqual(a, c);
        Assert.NotEqual(b, c);
    }
}
